"""
Writes glossary.py, refs.py and _work/meta.json from the lab's dump (_work/dump.json, made by ux-lab/scripts/dump-docs.ts).
Usage: python _tools/make_data.py
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
D = json.load(open(os.path.join(ROOT, "_work", "dump.json"), encoding="utf-8"))

gl = {k: {"term": v["title"], "plain": v["plain"], "example": v["example"] or "—", "from": f"Day {v['day']}"} for k, v in D["glossary"].items()}
open(os.path.join(HERE, "glossary.py"), "w", encoding="utf-8").write(
    '"""Generated by make_data.py from the lab glossary (data/gloss/dayN.ts). Do not edit by hand."""\nGLOSSARY = ' + json.dumps(gl, ensure_ascii=False, indent=1) + "\n"
)
refs = {k: v["full"] for k, v in D["refs"].items()}
open(os.path.join(HERE, "refs.py"), "w", encoding="utf-8").write(
    '"""Generated by make_data.py from the lab references (data/refs/dayN.ts). Do not edit by hand."""\nREFS = ' + json.dumps(refs, ensure_ascii=False, indent=1) + "\n"
)
meta = {}
for d, x in D["days"].items():
    s = x["spec"]
    meta[d] = {"case": s["caseName"], "role": s["role"], "heading": s["heading"]}
json.dump(meta, open(os.path.join(ROOT, "_work", "meta.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("glossary", len(gl), "refs", len(refs), "days", len(meta))
